<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Application;

use Throwable;
use DateInterval;
use Ramsey\Uuid\Uuid;
use Psr\EventDispatcher\EventDispatcherInterface;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\IdentificationMethod;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\PublicLoginAuthResponse;

/**
 * Core application service that drives the user authentication process during an OIDC authorization flow.
 *
 * Provides three entry points: standard credential-based authentication, pre-authentication for
 * flows where the user identity is already known (e.g., after MFA or consent steps), and
 * session-resumed authentication where a valid server-side session already exists.
 *
 * Each entry point verifies credentials or session validity through the LoginGateway, then persists
 * a new or reused session via the SessionStoreGateway and returns a PublicLoginAuthResponse containing
 * the session ID, authorization code data, and identity claims needed to build the OIDC redirect.
 *
 * Observability is provided through structured logging and distributed tracing spans attached to each
 * authentication attempt.
 */
class AuthenticateUser
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly LoginGateway $loginRepository,
        private readonly SessionStoreGateway $sessionStore
    ) {
    }

    /**
     * Resumes authentication from an existing server-side session identified by the provided session ID.
     * Skips credential validation and reuses the existing session when the challenges state confirms an active session.
     */
    public function sessionAuthenticated(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $issuer,
        string $csid,
        string $sessionId,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        $this->logDebug('OIDC session-authenticated start', ['tenant' => $tenant, 'sessionId' => $sessionId]);
        $span = $this->startSpan('oidc.session_authenticated', ['tenant' => $tenant]);
        try {
            $result = $this->saveIt(
                $this->loginRepository->fillPreLoadById($tenant, $request, $challenges),
                $request,
                $challenges,
                $issuer,
                $csid,
                false,
                $sessionId
            );
            $this->logInfo('OIDC session-authenticated ok', ['tenant' => $tenant, 'userId' => $result->auth->id ?? '']);
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $this->logWarning('OIDC session-authenticated error', ['tenant' => $tenant, 'error' => $ex instanceof LoginException ? ($ex->auth->error ?? '') : $ex->getMessage()]);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Performs pre-authentication for a flow where the user identity was established in a prior step.
     * Fills the authentication result from previously validated state rather than re-checking credentials,
     * so a state without that proof (a username that was only typed) is sent back to the login.
     */
    public function preAuthenticate(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        $this->logDebug('OIDC pre-authenticate start', ['tenant' => $tenant]);
        $span = $this->startSpan('oidc.pre_authenticate', ['tenant' => $tenant]);
        try {
            if (!$challenges->isIdentified()) {
                throw new LoginException(auth: AuthenticationResult::wrongCredentials($tenant, $challenges->username ?? ''));
            }
            $result = $this->saveIt(
                $this->loginRepository->fillPreAuthenticated($tenant, $request, $challenges),
                $request,
                $challenges,
                $issuer,
                $csid,
                false,
                null
            );
            $this->logInfo('OIDC pre-authenticate ok', ['tenant' => $tenant, 'userId' => $result->auth->id ?? '']);
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $this->logWarning('OIDC pre-authenticate error', ['tenant' => $tenant, 'error' => $ex instanceof LoginException ? ($ex->auth->error ?? '') : $ex->getMessage()]);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Authenticates a user by validating the supplied username and password against the login gateway.
     * On success, creates a new session (or reuses an existing csid-linked one) and dispatches a login event.
     */
    public function authenticate(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $username,
        string $password,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        $this->logDebug('OIDC authenticate start', ['tenant' => $tenant, 'username' => $username]);
        $span = $this->startSpan('oidc.authenticate', ['tenant' => $tenant]);
        try {
            $validation = $this->loginRepository->validatedUserData($tenant, $username, $password, $request);
            // Reaching here means the password was right, also when a step (MFA, terms...) is still pending.
            $challenges = $challenges->identifiedBy(IdentificationMethod::PASSWORD);
            $result = $this->saveIt(
                $validation,
                $request,
                $challenges,
                $issuer,
                $csid,
                true,
                null
            );
            $this->logInfo('OIDC authenticate ok', ['tenant' => $tenant, 'userId' => $result->auth->id ?? '']);
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $this->logWarning('OIDC authenticate error', ['tenant' => $tenant, 'username' => $username, 'error' => $ex instanceof LoginException ? ($ex->auth->error ?? '') : $ex->getMessage()]);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * True when the user must still enrol a second factor (no seed yet, and MFA required for the
     * user or the tenant): the only case in which a new TOTP seed may be shown or stored.
     */
    public function mfaEnrolmentPending(string $tenant, string $username): bool
    {
        return $this->loginRepository->mfaEnrolmentPending($tenant, $username);
    }

    /**
     * Records a wrong second factor (TOTP or recovery code) against the user's failed sign-in
     * attempts, so guessing it locks the account like guessing the password does.
     */
    public function secondFactorFailed(string $tenant, string $username): void
    {
        $this->logWarning('OIDC second factor rejected', ['tenant' => $tenant, 'username' => $username]);
        $this->loginRepository->markSecondFactorFailed($tenant, $username);
    }

    private function saveIt(
        AuthenticationResult $validation,
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $issuer,
        string $csid,
        bool $emitLoginEvent,
        ?string $activeSessionId
    ): PublicLoginAuthResponse {
        if (!$validation->valid) {
            throw new LoginException($validation, $validation->error ?? '', 401, null, $challenges);
        }

        if ($challenges->session && $activeSessionId !== null && $activeSessionId !== '') {
            // Never authorize from a session of another tenant: the client could not join it and
            // would miss its logout, so the authorization must not carry that sid.
            if ($this->sessionStore->findActiveSession($activeSessionId, $issuer) === null) {
                $this->logWarning('OIDC saveIt rejected session of another issuer', ['sessionId' => $activeSessionId]);
                throw new UnauthorizedException();
            }
            $this->logDebug('OIDC saveIt reusing active session', ['sessionId' => $activeSessionId]);
            $this->sessionStore->addSessionClient($activeSessionId, $issuer, $request->client->id);
            return $this->buildResponse($validation, $request, $issuer, $activeSessionId);
        }

        // Only methods with evidence (RFC 8176): a password checked in this flow, or a completed MFA
        // step with the method of its factor (`otp` for TOTP; a recovery code has no own value).
        $amr = array_values(array_filter([
            $challenges->identifiedBy === IdentificationMethod::PASSWORD ? 'pwd' : null,
            $challenges->withMfa ? $challenges->mfaMethod : null,
            $challenges->withMfa ? 'mfa' : null,
        ]));

        if (!$challenges->session) {
            $existingSessionId = $this->sessionStore->findActiveSessionIdByCsid($csid, $issuer);
            // Only the same user's session: another account signing in on this browser
            // (prompt=login or select_account) gets a session of its own.
            if ($existingSessionId !== null && $existingSessionId !== ''
                && $this->sessionStore->findActiveSession($existingSessionId, $issuer)?->userId === $validation->id
            ) {
                $this->logDebug('OIDC saveIt reusing csid session', ['existingSessionId' => $existingSessionId]);
                // The user has just authenticated in this flow, so max_age and the SSO lifetime count from now.
                $this->sessionStore->renewAuthentication($existingSessionId, $issuer, $amr);
                $this->sessionStore->addSessionClient($existingSessionId, $issuer, $request->client->id);
                return $this->buildResponse($validation, $request, $issuer, $existingSessionId);
            }
        }

        if ($emitLoginEvent) {
            $this->logDebug('OIDC saveIt dispatching login event', ['userId' => $validation->id ?? '']);
            $this->dispatcher->dispatch($validation);
        }

        $sessionId = Uuid::uuid4()->toString();
        $sessionExpiration = new DateInterval("P15D");

        $this->logDebug('OIDC saveIt creating new session', ['sessionId' => $sessionId, 'userId' => $validation->id ?? '']);
        $this->sessionStore->saveSession($sessionId, $request->client, $issuer, $challenges, $validation, $csid, $sessionExpiration, $amr);

        return $this->buildResponse($validation, $request, $issuer, $sessionId);
    }

    private function buildResponse(
        AuthenticationResult $validation,
        AuthenticationRequest $request,
        string $issuer,
        string $sessionId
    ): PublicLoginAuthResponse {
        return new PublicLoginAuthResponse(
            tenant: $validation->tenant ?? '',
            auth: $validation,
            issuer: $issuer,
            clientId: $request->client->id,
            sessionId: $sessionId,
            sessionExpiration: new DateInterval("P15D")
        );
    }
}
